  [399962] = { "Ottieni l'abilità Mutilazione:\n\n$I1\nAttacca istantaneamente con entrambe le armi, infliggendo il $N1% dei danni dell'arma più $N2 danni aggiuntivi con ciascuna arma. Danni aumentati del $N3% contro i bersagli avvelenati. Fornisce $N4 punti combo.", nil, 0x017062fe, nil, "um" },
  [399965] = { "Conferisce diversi miglioramenti ai tuoi veleni:\n\nQuando infliggi un qualsiasi altro veleno a un bersaglio, gli infliggi anche ⟦Deadly Poison=Veleno Mortale⟧.\n\nSe alla tua arma non è applicato alcun veleno, ha una probabilità di attivare ⟦Instant Poison=Veleno Istantaneo⟧ come se ⟦Instant Poison=Veleno Istantaneo⟧ fosse applicato.\n\n⟦Deadly Poison=Veleno Mortale⟧ e ⟦Instant Poison=Veleno Istantaneo⟧ ora traggono più danni dalla tua potenza d'attacco.\n\nIl tuo ⟦Deadly Poison=Veleno Mortale⟧ ora può essere attivo sui bersagli colpiti dal ⟦Deadly Poison=Veleno Mortale⟧ di un altro Ladro.", nil, 0xd4dbe68d, nil, "um" },
  [399966] = { "Equipaggia un oggetto per le gambe con una runa incisa per attivare un'abilità in questo spazio.", nil, 0x73ddef7a, nil, "um" },
  [399967] = { "Equipaggia un oggetto per le mani con una runa incisa per attivare un'abilità in questo spazio.", nil, 0x55d903a3, nil, "um" },
  [399969] = { "Ottieni l'abilità Miscela Letale:\n\n$I1\nConferisce diversi miglioramenti ai tuoi veleni:\n\nQuando infliggi un qualsiasi altro veleno a un bersaglio, gli infliggi anche Veleno Mortale.\n\nSe alla tua arma non è applicato alcun veleno, ha una probabilità di attivare Veleno Istantaneo come se Veleno Istantaneo fosse applicato.\n\nVeleno Mortale e Veleno Istantaneo ora traggono più danni dalla tua potenza d'attacco.\n\nIl tuo Veleno Mortale ora può essere attivo sui bersagli colpiti dal Veleno Mortale di un altro Ladro.", nil, 0x20d1c1da, nil, "um" },
  [399985] = { "Ti teletrasporti alle spalle del bersaglio e lo colpisci, infliggendo il $N1% dei danni dell'arma. Utilizzabile solo in Furtività. Fornisce $N2 punti combo.", nil, 0x8e972e2d, nil, "um" },
